// فصل 12 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 12 of the book — converted from the HTML edition; generated file.

export const n = 12;
export const num = "12";
export const title = "دیدن تغییر — diff، log، blame و bisect";
export const label = "فصل ۱۲ · diff و log";
export const part = 1;
export const html = "<p class=\"lead\">برای فهمیدن «چه عوض شد» فایل کامل را نخوان — تفاوت دو نسخه را بخوان. این فصل سه نوع diff، فیلتر log، و پیدا کردن کامیت خراب با bisect را جدا می‌کند.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>diff سه سطحی (unstaged / staged / بین کامیت‌ها) را جدا کنی</li>\n<li><code>log</code> را فیلتر کنی تا در ده هزار کامیت گم نشوی</li>\n<li>با <code>bisect</code> باگ را در log₂(n) قدم پیدا کنی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">📐 سه diff</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">سه نگاه</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>diff<span style=\"color: #F8F8F2\">                  </span><span style=\"color: #959077\"># Working vs Index</span>\ngit<span style=\"color: #F8F8F2\"> </span>diff<span style=\"color: #F8F8F2\"> </span>--staged<span style=\"color: #F8F8F2\">         </span><span style=\"color: #959077\"># Index vs HEAD</span>\ngit<span style=\"color: #F8F8F2\"> </span>diff<span style=\"color: #F8F8F2\"> </span>main...HEAD<span style=\"color: #F8F8F2\">      </span><span style=\"color: #959077\"># سه نقطه: از جد مشترک</span>\ngit<span style=\"color: #F8F8F2\"> </span>diff<span style=\"color: #F8F8F2\"> </span>main..HEAD<span style=\"color: #F8F8F2\">       </span><span style=\"color: #959077\"># دو نقطه: تفاوت نوک‌ها</span>\n</pre></div>\n<div class=\"callout callout-note\"><div class=\"callout-title\">سه‌نقطه در برابر دونقطه</div>\n<p><code>A...B</code> یعنی «تغییرات B از وقتی از A جدا شد» — دقیقاً همان چیزی که PR نشان می‌دهد. <code>A..B</code> نوک A را با نوک B مقایسه می‌کند و ممکن است تغییرات نامرتبط A را هم بیاورد.</p>\n</div>\n<p class=\"keep-next\">در VS Code کلیک روی فایل Changes = <code>git diff</code>. کلیک روی Staged = <code>git diff --staged</code>. <em>Open Changes</em> با <code>Alt</code> گاهی side-by-side را عوض می‌کند.</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">diff بهتر</span></div><pre><span style=\"color: #F8F8F2\">{</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.renderSideBySide&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.ignoreTrimWhitespace&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.hideUnchangedRegions.enabled&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span>\n<span style=\"color: #F8F8F2\">}</span>\n</pre></div>\n<p><code>hideUnchangedRegions</code> در فایل‌های بزرگ ۲۰۲۶ نجات‌دهنده است.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📜 log حرفه‌ای</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">جست‌وجوی تاریخچه</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>--grep<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&quot;refresh&quot;</span><span style=\"color: #F8F8F2\"> </span>-i\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>-S<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;rotateToken&quot;</span><span style=\"color: #F8F8F2\"> </span>-p<span style=\"color: #F8F8F2\">          </span><span style=\"color: #959077\"># pickaxe: کی این رشته آمد/رفت؟</span>\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>-G<span style=\"color: #F8F8F2\"> </span><span style=\"color: #E6DB74\">&quot;function rotate&quot;</span><span style=\"color: #F8F8F2\"> </span>-p<span style=\"color: #F8F8F2\">      </span><span style=\"color: #959077\"># regex روی diff</span>\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>--since<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&quot;2026-01-01&quot;</span><span style=\"color: #F8F8F2\"> </span>--until<span style=\"color: #FF4689\">=</span><span style=\"color: #E6DB74\">&quot;2026-03-01&quot;</span><span style=\"color: #F8F8F2\"> </span>--<span style=\"color: #F8F8F2\"> </span>src/auth.ts\ngit<span style=\"color: #F8F8F2\"> </span>log<span style=\"color: #F8F8F2\"> </span>--no-merges<span style=\"color: #F8F8F2\"> </span>--first-parent<span style=\"color: #F8F8F2\">   </span><span style=\"color: #959077\"># خط اصلی محصول</span>\n</pre></div>\n<p><code>--first-parent</code> روی <code>main</code> پر از merge، داستان محصول را می‌خواند نه داستان شاخه‌ها را.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🎯 bisect — کارآگاه باینری</span></span></h2>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">پیدا کردن کامیت خراب</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>start\ngit<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>bad<span style=\"color: #F8F8F2\">                </span><span style=\"color: #959077\"># HEAD خراب است</span>\ngit<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>good<span style=\"color: #F8F8F2\"> </span>v1.2.0<span style=\"color: #F8F8F2\">        </span><span style=\"color: #959077\"># این تگ سالم بود</span>\n<span style=\"color: #959077\"># Git وسط را checkout می‌کند — تست کن</span>\ngit<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>good<span style=\"color: #F8F8F2\">               </span><span style=\"color: #959077\"># یا bad</span>\ngit<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>reset\n</pre></div>\n<p class=\"keep-next\">اسکریپت‌پذیر:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">bisect خودکار</span></div><pre>git<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>start<span style=\"color: #F8F8F2\"> </span>HEAD<span style=\"color: #F8F8F2\"> </span>v1.2.0\ngit<span style=\"color: #F8F8F2\"> </span>bisect<span style=\"color: #F8F8F2\"> </span>run<span style=\"color: #F8F8F2\"> </span>npm<span style=\"color: #F8F8F2\"> test</span>\n</pre></div>\n<p>در VS Code می‌توانی هر گام را از Graph با Checkout انجام دهی؛ اما <code>bisect run</code> در ترمینال سریع‌تر است.</p>\n<div class=\"callout callout-tip\"><div class=\"callout-title\">-w و ignore-revs</div>\n<p>برای blame تمیز: فایل <code>.git-blame-ignore-revs</code> با هش کامیت‌های format-only، بعد:</p>\n<p><code>git config blame.ignoreRevsFile .git-blame-ignore-revs</code></p>\n</div>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Junior — git diff بدون آرگومان چه می‌کند؟</strong> Working در برابر Index.</p>\n<p><strong>Mid — pickaxe چیست؟</strong> <code>-S</code> کامیت‌هایی را می‌آورد که تعداد رخداد یک رشته را عوض کرده‌اند.</p>\n<p><strong>Senior — چرا first-parent برای main مهم است؟</strong> چون هر merge یک دنیای موازی است؛ برای رگرسیون محصول معمولاً فقط خط اصلی اهمیت دارد.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li><code>A...B</code> را از <code>A..B</code> جدا می‌کنی</li>\n<li><code>-S</code> را برای یافتن تولد یک تابع بلدی</li>\n<li>یک bisect موفق انجام داده‌ای</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> stash، worktree و sparse-checkout — چند کار موازی بدون هرج‌ومرج.</p></div>";
export default { n, num, title, label, part, html };
